declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';$id=max(0,(int)($_GET['id']??$_POST['id']??0));require_permission($id?'clients.edit':'clients.create');$client=null;if($id){$s=db()->prepare('SELECT * FROM clients WHERE id=?');$s->execute([$id]);$client=$s->fetch();if(!$client){http_response_code(404);exit('Cliente no encontrado.');}}$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle=$client?'Editar cliente':'Nuevo cliente';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=['company_name'=>trim((string)($_POST['company_name']??'')),'trade_name'=>trim((string)($_POST['trade_name']??'')),'tax_id'=>trim((string)($_POST['tax_id']??'')),'country'=>trim((string)($_POST['country']??'')),'city'=>trim((string)($_POST['city']??'')),'address'=>trim((string)($_POST['address']??'')),'website'=>trim((string)($_POST['website']??'')),'industry'=>trim((string)($_POST['industry']??'')),'status'=>(string)($_POST['status']??'active'),'start_date'=>($_POST['start_date']??'')?:null,'contact_name'=>trim((string)($_POST['contact_name']??'')),'contact_role'=>trim((string)($_POST['contact_role']??'')),'email'=>strtolower(trim((string)($_POST['email']??''))),'secondary_email'=>strtolower(trim((string)($_POST['secondary_email']??''))),'phone'=>trim((string)($_POST['phone']??'')),'whatsapp'=>trim((string)($_POST['whatsapp']??'')),'preferred_language'=>(string)($_POST['preferred_language']??'es'),'preferred_contact'=>(string)($_POST['preferred_contact']??'email'),'notes'=>trim((string)($_POST['notes']??'')),'owner_user_id'=>max(0,(int)($_POST['owner_user_id']??0))?:null];if($data['company_name']==='')$errors[]='El nombre de la empresa es obligatorio.';foreach(['email','secondary_email']as$f)if($data[$f]!==''&&!filter_var($data[$f],FILTER_VALIDATE_EMAIL))$errors[]='El '.$f.' no es válido.';if(!in_array($data['status'],['active','inactive','prospect'],true))$data['status']='active';if(!in_array($data['preferred_language'],['es','pt','en'],true))$data['preferred_language']='es';if(!in_array($data['preferred_contact'],['email','whatsapp','phone'],true))$data['preferred_contact']='email';if(!$errors){try{$logo=upload_client_logo($_FILES['logo']??[],$client['logo_path']??null);$vals=[$data['company_name'],$data['trade_name'],$data['tax_id'],$data['country'],$data['city'],$data['address'],$data['website'],$data['industry'],$data['status'],$data['start_date'],$logo,$data['contact_name'],$data['contact_role'],$data['email'],$data['secondary_email'],$data['phone'],$data['whatsapp'],$data['preferred_language'],$data['preferred_contact'],$data['notes'],$data['owner_user_id']];if($id){$vals[]=$id;db()->prepare('UPDATE clients SET company_name=?,trade_name=?,tax_id=?,country=?,city=?,address=?,website=?,industry=?,status=?,start_date=?,logo_path=?,contact_name=?,contact_role=?,email=?,secondary_email=?,phone=?,whatsapp=?,preferred_language=?,preferred_contact=?,notes=?,owner_user_id=? WHERE id=?')->execute($vals);}else{db()->prepare('INSERT INTO clients(company_name,trade_name,tax_id,country,city,address,website,industry,status,start_date,logo_path,contact_name,contact_role,email,secondary_email,phone,whatsapp,preferred_language,preferred_contact,notes,owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($vals);$id=(int)db()->lastInsertId();}if(isset($_POST['create_primary_contact'])&&$data['contact_name']!==''&&$data['email']!==''){$exists=db()->prepare('SELECT id FROM contacts WHERE client_id=? AND email=?');$exists->execute([$id,$data['email']]);if(!$exists->fetchColumn()){$parts=preg_split('/\s+/',trim($data['contact_name']));$first=array_shift($parts)?:$data['contact_name'];$last=implode(' ',$parts);db()->prepare('INSERT INTO contacts(client_id,first_name,last_name,job_title,email,secondary_email,phone,whatsapp,language,status,owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$first,$last,$data['contact_role'],$data['email'],$data['secondary_email'],$data['phone'],$data['whatsapp'],$data['preferred_language'],'active',$data['owner_user_id']]);}}log_activity($client?'Cliente actualizado':'Cliente creado',$id,null,$data['company_name']);flash('success',$client?'Cliente actualizado.':'Cliente creado.');redirect('client_view.php?id='.$id);}catch(Throwable$e){$errors[]=$e->getMessage();}}}
$v=fn($k,$d='')=>$_POST[$k]??($client[$k]??$d);require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" enctype="multipart/form-data" class="panel"><div class="panel-header"><div><h2><?=$client?'Actualizar ficha':'Registrar empresa o cliente'?></h2><span class="table-sub">La ficha centraliza contactos, servicios, negocios, cotizaciones y actividad.</span></div><a class="btn btn-light" href="<?=$client?'client_view.php?id='.$id:'clients.php'?>">Cancelar</a></div><div class="panel-body form-grid three"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-section full form-grid three"><h3>Información de la empresa</h3><label class="span-2">Nombre de la empresa *<input name="company_name" required value="<?=e($v('company_name'))?>"></label><label>Estado<select name="status"><?php foreach(['active'=>'Activo','prospect'=>'Prospecto','inactive'=>'Inactivo']as$k=>$l):?><option value="<?=$k?>" <?=$v('status','active')===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Nombre comercial<input name="trade_name" value="<?=e($v('trade_name'))?>"></label><label>RUT / RUC / CNPJ<input name="tax_id" value="<?=e($v('tax_id'))?>"></label><label>Rubro<input name="industry" value="<?=e($v('industry'))?>"></label><label>País<input name="country" value="<?=e($v('country'))?>"></label><label>Ciudad<input name="city" value="<?=e($v('city'))?>"></label><label>Fecha de inicio<input type="date" name="start_date" value="<?=e($v('start_date'))?>"></label><label class="span-2">Dirección<input name="address" value="<?=e($v('address'))?>"></label><label>Sitio web<input type="url" name="website" value="<?=e($v('website'))?>" placeholder="https://"></label><label>Responsable interno<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=(int)$u['id']?>" <?=(int)$v('owner_user_id',(int)$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label></div>
